// Build the Telegram report: status per demo, 7-day uptime, slow pages, Render refusals and failure streaks.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const secs = (ms) => (ms / 1000).toFixed(1) + 's';
const short = (s, n = 160) => { s = String(s ?? ''); return s.length > n ? s.slice(0, n) + '...' : s; };

// Slow-page rule: needs at least 3 earlier successful runs as a baseline.
const MIN_BASELINE_RUNS = 3;
const SLOW_FACTOR = 2;           // twice as slow as usual...
const SLOW_MIN_EXTRA_MS = 2000;  // ...and at least 2s slower
const SLOW_ABSOLUTE_MS = 10000;  // any start page over 10s is always slow

const run = $('Validate & flatten').all().map((i) => i.json);
const stats = Object.fromEntries(
  $input.all().filter((i) => i.json.demo).map((i) => [i.json.demo, i.json])
);

let down = 0, refused = 0, slow = 0, woke = 0;
const lines = run
  .sort((a, b) => a.demo.localeCompare(b.demo))
  .map((d) => {
    const s = stats[d.demo] ?? {};
    const week = s.uptime_pct != null ? ` · 7d ${s.uptime_pct}%` : '';
    const streak = Number(s.fail_streak) >= 2 ? ` (${s.fail_streak} runs in a row)` : '';

    if (!d.ok) {
      down++;
      if (/^Render refused to wake/i.test(d.problem ?? '')) {
        refused++;
        return `⛔ <b>${esc(d.demo)}</b>: Render refused to wake it${streak}${week}`;
      }
      const why = d.problem ? `\n     ${esc(short(d.problem))}` : '';
      return `❌ <b>${esc(d.demo)}</b>: DOWN${streak}${week}${why}`;
    }

    if (d.was_asleep === true) woke++;
    const state = d.was_asleep === true ? 'woke up'
      : d.was_asleep === false ? 'already awake'
      : d.wake_ms != null ? `woke in ${secs(d.wake_ms)}` : 'up';

    if (d.page_ms == null) return `✅ <b>${esc(d.demo)}</b>: ${state}${week}`;

    const usual = Number(s.usual_page_ms);
    const hasBaseline = Number(s.baseline_runs) >= MIN_BASELINE_RUNS && usual > 0;
    const isSlow =
      d.page_ms > SLOW_ABSOLUTE_MS ||
      (hasBaseline && d.page_ms > usual * SLOW_FACTOR && d.page_ms - usual >= SLOW_MIN_EXTRA_MS);

    if (isSlow) {
      slow++;
      const vs = hasBaseline ? ` (usually ${secs(usual)})` : '';
      return `🐢 <b>${esc(d.demo)}</b>: ${state}, slow page ${secs(d.page_ms)}${vs}${week}`;
    }
    return `✅ <b>${esc(d.demo)}</b>: ${state}, page ${secs(d.page_ms)}${week}`;
  });

const when = DateTime.fromISO(run[0].run_at).setZone('Asia/Dubai').toFormat('dd LLL, HH:mm');
let header;
if (down) header = `🚨 <b>Demo check: ${down} of ${run.length} down</b>`;
else if (slow) header = `🟡 <b>Demo check: all ${run.length} up, ${slow} slow</b>`;
else header = `🟢 <b>Demo check: all ${run.length} up</b>`;

let footer = '';
if (refused) footer = `\n\n<i>⛔ = Render's wake-up limit. The app isn't broken, but visitors can't open it until Render allows it to start again. Full details are in ops.demo_checks.</i>`;

return [{
  json: {
    text: `${header}\n<i>${when} (Dubai)</i>\n\n${lines.join('\n')}${footer}`,
    silent: down === 0, // only failures ring; slow pages arrive silently
    down, refused, slow, woke,
  },
}];

