// Weekly summary: last 7 days per demo, compared with the 7 days before.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = $input.all().map((i) => i.json).filter((r) => r.demo);

const end = $now.setZone('Asia/Dubai');
const range = `${end.minus({ days: 6 }).toFormat('dd LLL')} to ${end.toFormat('dd LLL')}`;

if (rows.length === 0) {
  return [{ json: { text: `📅 <b>Weekly demo summary</b>\n<i>${range}</i>\n\nNo demo checks were recorded in the last 7 days.` } }];
}

const pct = (ok, n) => (n > 0 ? Math.round((100 * ok) / n) : null);
let totalChecks = 0, totalPassed = 0, totalRefused = 0;

const lines = rows.map((r) => {
  const checks = Number(r.checks), passed = Number(r.passed), refused = Number(r.refused), woke = Number(r.woke);
  totalChecks += checks; totalPassed += passed; totalRefused += refused;
  const up = pct(passed, checks);
  const prevUp = pct(Number(r.prev_passed), Number(r.prev_checks));

  const icon = checks === 0 ? '⚪' : up === 100 ? '✅' : up >= 80 ? '🟡' : '❌';
  let line = `${icon} <b>${esc(r.demo)}</b>: ${up ?? '-'}% up (${passed}/${checks})`;
  if (prevUp != null && up != null && prevUp !== up) line += `, was ${prevUp}%`;

  const extras = [];
  if (refused) extras.push(`${refused}× refused by Render`);
  if (woke) extras.push(`woken ${woke}×`);
  if (r.avg_page_s != null) {
    let page = `page avg ${r.avg_page_s}s, slowest ${r.max_page_s}s`;
    if (r.prev_avg_page_s != null) {
      const diff = Number(r.avg_page_s) - Number(r.prev_avg_page_s);
      if (Math.abs(diff) >= 1) page += ` (${diff > 0 ? '+' : ''}${diff.toFixed(1)}s vs last week)`;
    }
    extras.push(page);
  }
  if (extras.length) line += `\n     ${extras.join(' · ')}`;
  return line;
});

const overall = pct(totalPassed, totalChecks);
let header = `📅 <b>Weekly demo summary</b>\n<i>${range}</i>\n\nOverall: <b>${overall ?? '-'}%</b> (${totalPassed}/${totalChecks} checks passed)`;
if (totalRefused) header += `\n⛔ ${totalRefused} failed check${totalRefused > 1 ? 's were' : ' was'} Render refusing to wake a demo`;

return [{ json: { text: `${header}\n\n${lines.join('\n')}` } }];

// The one place to change settings for this workflow.
return [{
  json: {
    // origin: the demo's Render address (woken directly); public: the address visitors use (through demo-proxy)
    demos: [
      { name: 'AutoServicePro', origin: 'https://autoservicepro-hrqe.onrender.com', public: 'autoservice-demo.naja.live' },
      { name: 'FuelStationPro', origin: 'https://fuelstationpro-demo.onrender.com', public: 'fuelstation-demo.naja.live' },
      { name: 'MarginTracker', origin: 'https://margintracker-demo.onrender.com', public: 'margintracker-demo.naja.live' },
      { name: 'StockPOS', origin: 'https://stockpos.onrender.com', public: 'stockpos-demo.naja.live' },
    ],
    wake_timeout_ms: 100000, // Render holds the wake request while the app boots (20 to 45 s seen)
    retry_wait_ms: 30000, // one more look after this, if the first answer wasn't the app
    asleep_if_slower_ms: 5000, // an awake demo answers /health in under a second

    // Cloudflare D1 (the marketing Worker's database): records the run, so the Worker's own check stands by
    cf_account: 'YOUR_CLOUDFLARE_ACCOUNT_ID',
    d1_database: 'YOUR_D1_DATABASE_ID',
  },
}];

// The daily demo check, from n8n's own server. Render wakes a sleeping free service for a request from a normal
// address (a visitor, this server) but refuses one from Cloudflare's shared addresses, so a check running in a
// Cloudflare Worker was refused every morning. Per demo: one wake request to Render directly (Render holds it while
// the app boots), one more look if needed, the start page timed, and the public address checked. Output: the same
// payload the Worker sends to the webhook, so everything from "Validate & flatten" on is shared.
const s = $('Check settings').first().json;
const helpers = this.helpers;
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const errMsg = (e) => (e instanceof Error ? e.message : String(e));

async function get(url, timeout, accept) {
  return helpers.httpRequest({
    method: 'GET',
    url,
    headers: { Accept: accept },
    timeout,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    disableFollowRedirect: true,
  });
}
const header = (res, k) => String(res?.headers?.[k] ?? '');

/** awake: the app answers plain text. refused: Render's wake limit or challenge. waking: anything else. */
async function health(origin) {
  try {
    const res = await get(`${origin}/health`, s.wake_timeout_ms, 'text/plain');
    if (res.statusCode === 200 && header(res, 'content-type').startsWith('text/plain')) return { state: 'awake', status: 200 };
    const refused = header(res, 'x-render-routing') === 'hibernate-rate-limited' || header(res, 'cf-mitigated') === 'challenge';
    const detail = `health check answered ${res.statusCode}, x-render-routing: ${header(res, 'x-render-routing') || 'none'}, rndr-id: ${header(res, 'rndr-id') || 'none'}`;
    return { state: refused ? 'refused' : 'waking', status: res.statusCode, detail };
  } catch (e) {
    return { state: 'waking', status: null, detail: `health check failed: ${errMsg(e)}` };
  }
}

/** The start page, following at most 3 redirects (the apps send / to their login page). */
async function loadPage(origin) {
  let url = `${origin}/`;
  for (let hop = 1; ; hop++) {
    const res = await get(url, 30000, 'text/html');
    const to = header(res, 'location');
    if (res.statusCode < 300 || res.statusCode >= 400 || !to || hop === 3) return res;
    // Stay on the Render address: StockPOS redirects to its public address (APP_URL), where the demo-proxy would
    // answer with its loading page (503) instead of the app.
    const path = /^https?:\/\//.test(to) ? to.replace(/^https?:\/\/[^/]+/, '') || '/' : to;
    url = path.startsWith('/') ? `${origin}${path}` : `${origin}/${path}`;
  }
}

async function checkDemo(d) {
  const failed = (problem, status_code, extra = {}) => ({ name: d.name, ok: false, wake_ms: null, was_asleep: false, page_ms: null, status_code, problem, ...extra });
  const t0 = Date.now();
  let h = await health(d.origin);
  if (h.state === 'waking') {
    await sleep(s.retry_wait_ms);
    h = await health(d.origin);
  }
  const wakeMs = Date.now() - t0;
  const was_asleep = wakeMs > s.asleep_if_slower_ms;
  const wake = { was_asleep, wake_ms: was_asleep ? wakeMs : null };
  if (h.state === 'refused') return failed(`Render refused to wake it (rate limited) (${h.detail})`, h.status, wake);
  if (h.state === 'waking') return failed(`did not wake up within ${Math.round(wakeMs / 1000)} s (${h.detail})`, h.status, wake);

  const p0 = Date.now();
  let page;
  try {
    page = await loadPage(d.origin);
  } catch (e) {
    return failed(`the start page failed: ${errMsg(e)}`, null, wake);
  }
  const page_ms = Date.now() - p0;
  if (page.statusCode < 200 || page.statusCode >= 300) return failed(`the start page answered ${page.statusCode}`, page.statusCode, { ...wake, page_ms });

  // The visitors' address goes through the demo-proxy Worker; robots.txt is answered by the proxy itself,
  // so this checks it without touching the app or sending a "visitor woke a demo" alert.
  try {
    const pub = await get(`https://${d.public}/robots.txt`, 15000, 'text/plain');
    if (pub.statusCode !== 200) return failed(`the public address ${d.public} answered ${pub.statusCode} (demo-proxy)`, pub.statusCode, { ...wake, page_ms });
  } catch (e) {
    return failed(`the public address ${d.public} failed: ${errMsg(e)} (demo-proxy)`, null, { ...wake, page_ms });
  }
  return { name: d.name, ok: true, ...wake, page_ms, status_code: page.statusCode, problem: null };
}

const ranAt = new Date().toISOString();
const demos = await Promise.all(s.demos.map(checkDemo));
const down = demos.filter((d) => !d.ok).map((d) => d.name);
return [{ json: { body: { ran_at: ranAt, source: 'n8n-demo-check', demos }, summary: JSON.stringify({ checked: demos.length, down }) } }];
